    @Test
    void 'groovy core - Comments'() {
        expectAst('''\
            |#!/usr/bin/env groovy
            |/**
            | * Created on 2016/08/16.
            | */
            |
            |// this is a line comment
            |
            |println /* method name */ 1 /* one */ /* followed by plus */ + /* plus */ 2 /* two */
            |+3
            |'''.stripMargin(), '''\
            |<Module line="-1" column="-1" lastLine="-1" lastColumn="-1">
            |  <BlockStatement line="-1" column="-1" lastLine="-1" lastColumn="-1">
            |    <ExpressionStatement line="8" column="1" lastLine="8" lastColumn="76">
            |      <MethodCallExpression line="8" column="1" lastLine="8" lastColumn="76" implicitThis="true">
            |        <ConstantExpression line="8" column="1" lastLine="8" lastColumn="8" value="println"/>
            |        <BinaryExpression line="8" column="27" lastLine="8" lastColumn="76" token="+">
            |          <ConstantExpression line="8" column="27" lastLine="8" lastColumn="28" value="1"/>
            |          <ConstantExpression line="8" column="75" lastLine="8" lastColumn="76" value="2"/>
            |        </BinaryExpression>
            |      </MethodCallExpression>
            |    </ExpressionStatement>
            |    <ExpressionStatement line="9" column="1" lastLine="9" lastColumn="3">
            |      <ConstantExpression line="9" column="1" lastLine="9" lastColumn="3" value="3"/>
            |    </ExpressionStatement>
            |  </BlockStatement>
            |</Module>'''.stripMargin())
        def comments02 = '''\
            |/**
            | * test class Comments
            | */
            |public class Comments {
            |    /**
            |     * test Comments.SOME_VAR
            |     */
            |    public static final String SOME_VAR = 'SOME_VAR';
            |    /**
            |     * test Comments.SOME_VAR2
            |     */
            |    public static final String SOME_VAR2 = 'SOME_VAR2';
            |
            |    public static final String SOME_VAR3 = 'SOME_VAR3';
            |
            |    /**
            |     * test Comments.SOME_VAR4
            |     */
            |    // no groovydoc for SOME_VAR4
            |    public static final String SOME_VAR4 = 'SOME_VAR4';
            |
            |
            |    /**
            |     * test Comments.constructor1
            |     */
            |    public Comments() {
            |
            |    }
            |
            |    /**
            |     * test Comments.m1
            |     */
            |    def m1() {
            |        // executing m1
            |    }
            |
            |    /*
            |     * test Comments.m2
            |     */
            |    private m2() {
            |        // executing m2
            |    }
            |
            |    /**
            |     * test Comments.m3
            |     */
            |    public void m3() {
            |        // executing m3
            |    }
            |
            |    /**
            |     * test class InnerClazz
            |     */
            |    static class InnerClazz {
            |        /**
            |         * test InnerClazz.SOME_VAR3
            |         */
            |        public static final String SOME_VAR3 = 'SOME_VAR3';
            |        /**
            |         * test InnerClazz.SOME_VAR4
            |         */
            |        public static final String SOME_VAR4 = 'SOME_VAR4';
            |
            |        /**
            |         * test Comments.m4
            |         */
            |        public void m4() {
            |            // executing m4
            |        }
            |
            |        /**
            |         * test Comments.m5
            |         */
            |        public void m5() {
            |            // executing m5
            |        }
            |    }
            |
            |    /**
            |     * test class InnerEnum
            |     */
            |    static enum InnerEnum {
            |        /**
            |         * InnerEnum.NEW
            |         */
            |        NEW,
            |
            |        /**
            |         * InnerEnum.OLD
            |         */
            |        OLD
            |    }
            |
            |    static enum InnerEnum2 {}
            |}
            |
            |/**
            | * test class Comments2
            | */
            |class Comments2 {
            |    /*
            |     * test Comments.SOME_VAR
            |     */
            |    public static final String SOME_VAR = 'SOME_VAR';
            |}
            |
            |class Comments3 {}
            |
            |/**
            | * test someScriptMethod1
            | */
            |void someScriptMethod1() {}
            |
            |/*
            | * test someScriptMethod2
            | */
            |void someScriptMethod2() {}
            |'''.stripMargin()
        expectAst(comments02, '''\
            |<Module line="-1" column="-1" lastLine="-1" lastColumn="-1">
            |  <ClassNode line="4" column="1" lastLine="95" lastColumn="2" kind="class" name="Comments">
            |    <FieldNode line="8" column="5" lastLine="8" lastColumn="53" name="SOME_VAR" type="String" modifiers="public static final">
            |      <ConstantExpression line="8" column="43" lastLine="8" lastColumn="53" value="SOME_VAR"/>
            |    </FieldNode>
            |    <FieldNode line="12" column="5" lastLine="12" lastColumn="55" name="SOME_VAR2" type="String" modifiers="public static final">
            |      <ConstantExpression line="12" column="44" lastLine="12" lastColumn="55" value="SOME_VAR2"/>
            |    </FieldNode>
            |    <FieldNode line="14" column="5" lastLine="14" lastColumn="55" name="SOME_VAR3" type="String" modifiers="public static final">
            |      <ConstantExpression line="14" column="44" lastLine="14" lastColumn="55" value="SOME_VAR3"/>
            |    </FieldNode>
            |    <FieldNode line="20" column="5" lastLine="20" lastColumn="55" name="SOME_VAR4" type="String" modifiers="public static final">
            |      <ConstantExpression line="20" column="44" lastLine="20" lastColumn="55" value="SOME_VAR4"/>
            |    </FieldNode>
            |    <ConstructorNode line="26" column="5" lastLine="28" lastColumn="6" name="&lt;init&gt;">
            |      <BlockStatement line="26" column="23" lastLine="28" lastColumn="6"/>
            |    </ConstructorNode>
            |    <MethodNode line="33" column="5" lastLine="35" lastColumn="6" name="m1" returnType="java.lang.Object">
            |      <BlockStatement line="33" column="14" lastLine="35" lastColumn="6"/>
            |    </MethodNode>
            |    <MethodNode line="40" column="5" lastLine="42" lastColumn="6" name="m2" modifiers="private" returnType="java.lang.Object">
            |      <BlockStatement line="40" column="18" lastLine="42" lastColumn="6"/>
            |    </MethodNode>
            |    <MethodNode line="47" column="5" lastLine="49" lastColumn="6" name="m3" returnType="void">
            |      <BlockStatement line="47" column="22" lastLine="49" lastColumn="6"/>
            |    </MethodNode>
            |  </ClassNode>
            |  <ClassNode line="54" column="5" lastLine="77" lastColumn="6" kind="class" name="Comments$InnerClazz" modifiers="static">
            |    <FieldNode line="58" column="9" lastLine="58" lastColumn="59" name="SOME_VAR3" type="String" modifiers="public static final">
            |      <ConstantExpression line="58" column="48" lastLine="58" lastColumn="59" value="SOME_VAR3"/>
            |    </FieldNode>
            |    <FieldNode line="62" column="9" lastLine="62" lastColumn="59" name="SOME_VAR4" type="String" modifiers="public static final">
            |      <ConstantExpression line="62" column="48" lastLine="62" lastColumn="59" value="SOME_VAR4"/>
            |    </FieldNode>
            |    <MethodNode line="67" column="9" lastLine="69" lastColumn="10" name="m4" returnType="void">
            |      <BlockStatement line="67" column="26" lastLine="69" lastColumn="10"/>
            |    </MethodNode>
            |    <MethodNode line="74" column="9" lastLine="76" lastColumn="10" name="m5" returnType="void">
            |      <BlockStatement line="74" column="26" lastLine="76" lastColumn="10"/>
            |    </MethodNode>
            |  </ClassNode>
            |  <ClassNode line="82" column="5" lastLine="92" lastColumn="6" kind="enum" name="Comments$InnerEnum" modifiers="static" extends="java.lang.Enum&lt;Comments.InnerEnum&gt;">
            |    <FieldNode line="86" column="9" lastLine="86" lastColumn="12" name="NEW" type="Comments$InnerEnum" modifiers="public static final" enumConstant="true"/>
            |    <FieldNode line="91" column="9" lastLine="91" lastColumn="12" name="OLD" type="Comments$InnerEnum" modifiers="public static final" enumConstant="true"/>
            |  </ClassNode>
            |  <ClassNode line="94" column="5" lastLine="94" lastColumn="30" kind="enum" name="Comments$InnerEnum2" modifiers="static" extends="java.lang.Enum&lt;Comments.InnerEnum2&gt;"/>
            |  <ClassNode line="100" column="1" lastLine="105" lastColumn="2" kind="class" name="Comments2">
            |    <FieldNode line="104" column="5" lastLine="104" lastColumn="53" name="SOME_VAR" type="String" modifiers="public static final">
            |      <ConstantExpression line="104" column="43" lastLine="104" lastColumn="53" value="SOME_VAR"/>
            |    </FieldNode>
            |  </ClassNode>
            |  <ClassNode line="107" column="1" lastLine="107" lastColumn="19" kind="class" name="Comments3"/>
            |  <MethodNode line="112" column="1" lastLine="112" lastColumn="28" name="someScriptMethod1" returnType="void">
            |    <BlockStatement line="112" column="26" lastLine="112" lastColumn="28"/>
            |  </MethodNode>
            |  <MethodNode line="117" column="1" lastLine="117" lastColumn="28" name="someScriptMethod2" returnType="void">
            |    <BlockStatement line="117" column="26" lastLine="117" lastColumn="28"/>
            |  </MethodNode>
            |</Module>'''.stripMargin())

        def groovydocConfiguration = new CompilerConfiguration(CompilerConfiguration.DEFAULT)
        groovydocConfiguration.setOptimizationOptions([(CompilerConfiguration.GROOVYDOC): true])
        def newAST = parseModule(comments02, groovydocConfiguration)
        List<ClassNode> classes = new ArrayList<>(newAST.classes).sort { c1, c2 -> c1.name <=> c2.name }
        List<MethodNode> methods = new ArrayList<>(newAST.methods).sort { m1, m2 -> m1.name <=> m2.name }

        assert  classes[0].groovydoc.content.replaceAll(/\r?\n/, '')            == '/** * test class Comments */'
        assert  classes[0].fields[0].groovydoc.content.replaceAll(/\r?\n/, '')  == '/**     * test Comments.SOME_VAR     */'
        assert  classes[0].fields[1].groovydoc.content.replaceAll(/\r?\n/, '')  == '/**     * test Comments.SOME_VAR2     */'
        assert !classes[0].fields[2].groovydoc.isPresent()
        assert !classes[0].fields[3].groovydoc.isPresent()
        assert  classes[0].declaredConstructors[0].groovydoc.content.replaceAll(/\r?\n/, '') == '/**     * test Comments.constructor1     */'
        assert  classes[0].methods[0].groovydoc.content.replaceAll(/\r?\n/, '') == '/**     * test Comments.m1     */'
        assert !classes[0].methods[1].groovydoc.isPresent()
        assert  classes[0].methods[2].groovydoc.content.replaceAll(/\r?\n/, '') == '/**     * test Comments.m3     */'

        assert  classes[1].groovydoc.content.replaceAll(/\r?\n/, '')            == '/**     * test class InnerClazz     */'
        assert  classes[1].fields[0].groovydoc.content.replaceAll(/\r?\n/, '')  == '/**         * test InnerClazz.SOME_VAR3         */'
        assert  classes[1].fields[1].groovydoc.content.replaceAll(/\r?\n/, '')  == '/**         * test InnerClazz.SOME_VAR4         */'
        assert  classes[1].methods[0].groovydoc.content.replaceAll(/\r?\n/, '') == '/**         * test Comments.m4         */'
        assert  classes[1].methods[1].groovydoc.content.replaceAll(/\r?\n/, '') == '/**         * test Comments.m5         */'

        assert  classes[2].groovydoc.content.replaceAll(/\r?\n/, '')            == '/**     * test class InnerEnum     */'
        assert  classes[2].fields[0].groovydoc.content.replaceAll(/\r?\n/, '')  == '/**         * InnerEnum.NEW         */'
        assert  classes[2].fields[1].groovydoc.content.replaceAll(/\r?\n/, '')  == '/**         * InnerEnum.OLD         */'

        assert !classes[3].groovydoc.isPresent()

        assert !classes[4].fields[0].groovydoc.isPresent()

        assert !classes[5].groovydoc.isPresent()

        assert  methods[0].groovydoc.content.replaceAll(/\r?\n/, '') == '/** * test someScriptMethod1 */'
        assert !methods[1].groovydoc.isPresent()
    }

