    @Test
    void 'groovy core - Closure'() {
        expectAst('''\
            |{->}
            |
            |'''.stripMargin(), '''\
            |<Module line="-1" column="-1" lastLine="-1" lastColumn="-1">
            |  <BlockStatement line="-1" column="-1" lastLine="-1" lastColumn="-1">
            |    <ExpressionStatement line="1" column="1" lastLine="1" lastColumn="5">
            |      <ClosureExpression line="1" column="1" lastLine="1" lastColumn="5" implicitIt="true">
            |        <BlockStatement line="1" column="4" lastLine="1" lastColumn="4"/>
            |      </ClosureExpression>
            |    </ExpressionStatement>
            |  </BlockStatement>
            |</Module>'''.stripMargin())
        expectAst('''\
            |{->12}
            |
            |'''.stripMargin(), '''\
            |<Module line="-1" column="-1" lastLine="-1" lastColumn="-1">
            |  <BlockStatement line="-1" column="-1" lastLine="-1" lastColumn="-1">
