            |      <ClosureExpression line="1" column="1" lastLine="1" lastColumn="7" implicitIt="true">
            |        <BlockStatement line="1" column="4" lastLine="1" lastColumn="6">
            |          <ExpressionStatement line="1" column="4" lastLine="1" lastColumn="6">
            |            <ConstantExpression line="1" column="4" lastLine="1" lastColumn="6" value="12"/>
