    @Test
    void 'groovy core - NegativeRelationalOperators'() {
        expectAst('''\
            |assert 'a' instanceof String
            |assert 'a' !instanceof Integer
            |assert 1 !instanceof String
            |assert null !instanceof String
            |assert 1 in [1, 2]
            |assert 3 !in [1, 2]
            |assert 3 !in ['1', '2']
            |assert '3' !in [1, 2]
            |assert '3' !in ['1', '2']
            |assert null !in ['1', '2']
            |assert null !in [1, 2]
            |
            |boolean interesting = false
            |assert !interesting
            |
            |boolean instanceofboolean = false
            |assert !instanceofboolean
            |
            |assert 1 !in[2, 3]
            |assert 1 !in([2, 3])
