    @Test
    void 'groovy core - Synchronized'() {
        expectAst('''\
            |synchronized ('a')
            |{
            |    assert true
            |}
            |
            |synchronized ('a') {
            |    assert true
            |}
            |
            |synchronized ('a') {assert true
            |}
            |
            |synchronized ('a') {assert true}
            |
            |synchronized ('a') {assert true;}
            |
            |synchronized ('a') {
            |    assert true
            |    assert true
            |}
            |
            |synchronized ('a') {
            |    assert true;
            |    assert true
            |}
            |
            |synchronized ('a') {
            |    assert true; assert true
            |}
            |
            |synchronized ('a') {assert true; assert true
            |}
            |
            |synchronized ('a') {assert true; assert true}
            |
            |synchronized ('a') {assert true; assert true;}
