            |package core
            |
            |@groovy.transform.TupleConstructor(defaults=false)
            |record Point(int x, int y, String color) {
            |    public Point {
            |        x = -x;
            |        Objects.requireNonNull(color);
            |        color = color.toUpperCase();
            |    }
            |
            |    public Point(int x, int y) {
            |        this(x, y, 'Blue');
            |    }
