    @Test
    void 'groovy core - Groovydoc'() {
        def runtimeGroovydocConfiguration = new CompilerConfiguration(CompilerConfiguration.DEFAULT)
        runtimeGroovydocConfiguration.setOptimizationOptions([(CompilerConfiguration.RUNTIME_GROOVYDOC): true])
        def groovydoc01 = '''\
            |/**@
            | * class AA
            | */
            |class AA {
            |    /**@
            |     * field SOME_FIELD
            |     */
            |    public static final int SOME_FIELD = 1;
            |
            |    /**@
            |     * constructor AA
            |     */
            |    public AA() {
            |
            |    }
            |
            |    /**@
            |     * method m
            |     */
            |    public void m() {
            |
            |    }
            |
            |    /**@
            |     * class InnerClass
            |     */
            |    class InnerClass {
            |
            |    }
            |
            |
            |}
            |
            |/**@
            | * annotation BB
            | */
            |@interface BB {
            |
            |}
            |
            |assert AA.class.groovydoc.content.contains('class AA')
            |assert AA.class.getMethod('m').groovydoc.content.contains('method m')
            |assert AA.class.getConstructor().groovydoc.content.contains('constructor AA')
            |assert AA.class.getField('SOME_FIELD').groovydoc.content.contains('field SOME_FIELD')
            |assert AA.class.getDeclaredClasses().find {it.simpleName.contains('InnerClass')}.groovydoc.content.contains('class InnerClass')
            |assert BB.class.groovydoc.content.contains('annotation BB')
            |
            |'''.stripMargin()
        expectAst(groovydoc01, '''\
            |<Module line="-1" column="-1" lastLine="-1" lastColumn="-1">
            |  <BlockStatement line="-1" column="-1" lastLine="-1" lastColumn="-1">
            |    <AssertStatement line="41" column="1" lastLine="41" lastColumn="55">
            |      <BooleanExpression line="41" column="8" lastLine="41" lastColumn="55">
            |        <MethodCallExpression line="41" column="8" lastLine="41" lastColumn="55">
            |          <PropertyExpression line="41" column="26" lastLine="41" lastColumn="34">
            |            <PropertyExpression line="41" column="16" lastLine="41" lastColumn="26">
