    @Test
    void 'groovy core - FieldDeclaration'() {
        expectAst('''\
            |class Base {
            |    def num = 0
            |}
            |
            |class FieldHolder extends Base {
            |    def num
            |    private num = 1
            |}
            |
            |class FieldHolder2 extends Base {
            |    private num = 2
            |    def num
            |}
            |
            |assert 1 == new FieldHolder().num
            |assert 2 == new FieldHolder2().num
            |
            |'''.stripMargin(), '''\
            |<Module line="-1" column="-1" lastLine="-1" lastColumn="-1">
            |  <BlockStatement line="-1" column="-1" lastLine="-1" lastColumn="-1">
            |    <AssertStatement line="15" column="1" lastLine="15" lastColumn="34">
            |      <BooleanExpression line="15" column="8" lastLine="15" lastColumn="34">
