    @Test
    void 'groovy core - SafeChainOperator'() {
        expectAst('''\
            |import groovy.transform.CompileStatic
            |
            |def testSCO() {
            |    assert  3 == 1??.plus(2)
            |    assert  6 == 1??.plus(2).plus(3)
