    @Test
    void 'groovy core - val'() {
        expectAst('''\
            |// basic val declaration
            |val name = "Groovy"
            |assert "Groovy" == name
            |
            |// val as closure parameter name
            |[1, 2, 3].each { val ->
            |    assert 0 < val && val < 4
            |}
            |
            |// val as variable name (contextual keyword)
            |val val = "val variable name"
            |assert "val variable name" == val
            |
            |// val in map key
            |def m = [val: 42]
            |assert m.val == 42
            |
            |// val with different types
            |val x = 42
            |assert x == 42
            |val s = "hello"
            |assert s.class == String
            |
            |// shallow finality - mutation OK
            |val list = [1, 2, 3]
            |list << 4
            |assert list == [1, 2, 3, 4]
            |
            |// final val is redundant but works
            |final val y = 10
            |assert y == 10
            |
            |// for loop with val
            |for (val i in [1, 2, 3]) { assert i > 0 }
            |
            |// GString interpolation
            |val g = 99
            |assert "$g" == "99"
            |
            |'''.stripMargin(), '''\
            |<Module line="-1" column="-1" lastLine="-1" lastColumn="-1">
            |  <BlockStatement line="-1" column="-1" lastLine="-1" lastColumn="-1">
            |    <ExpressionStatement line="2" column="1" lastLine="2" lastColumn="20">
            |      <DeclarationExpression line="2" column="1" lastLine="2" lastColumn="20" token="=">
            |        <VariableExpression line="2" column="5" lastLine="2" lastColumn="9" name="name"/>
