    @Test
    void 'groovy core - block comments'() {
        expectAst('''\
            |/* leading */
            |def x = 1
            |assert x == 1
            |
            |/** groovydoc-looking */
            |def y = 2
            |assert y == 2
            |
            |/* inner /* is just text */
            |assert true
            |
            |/* empty closer follows */
